// Uniform declarations (make sure these are provided by your framework)
uniform vec3 iResolution;   // viewport resolution (in pixels)
uniform sampler2D iChannel0; // input texture
uniform vec2 iBlurDir;      // normalized blur direction (e.g. vec2(1.0, 0.0) for horizontal)
uniform float iBlurAmount;  // blur amount in screen pixels

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Pixelation settings
    float pixelSize = 2.0; // in screen pixels

    // Compute base pixel position (quantized)
    vec2 basePixelPos = floor(fragCoord / pixelSize);
    vec2 baseUV = basePixelPos * pixelSize / iResolution.xy;

    // Motion blur settings
    const int NUM_SAMPLES = 8; // number of samples along blur direction
    // Convert blur amount (in screen pixels) into pixel grid units.
    // Since each "pixel" in our pixelated grid is 'pixelSize' screen pixels wide,
    // dividing by pixelSize gives the offset in grid units.
    vec2 blurVector = (iBlurAmount / pixelSize) * normalize(iBlurDir);

    // Accumulate texture samples along the motion blur line.
    // We'll sample along offsets from -0.5 to +0.5 of the total blur vector.
    vec3 colorAccum = vec3(0.0);
    for (int i = 0; i < NUM_SAMPLES; i++)
    {
        float t = float(i) / float(NUM_SAMPLES - 1) - 0.5; // from -0.5 to 0.5
        vec2 samplePixelPos = basePixelPos + t * blurVector;
        vec2 sampleUV = samplePixelPos * pixelSize / iResolution.xy;
        colorAccum += texture(iChannel0, sampleUV).rgb;
    }
    vec3 color = colorAccum / float(NUM_SAMPLES);

    // Convert accumulated color to grayscale
    float gray = dot(color, vec3(0.299, 0.587, 0.114));

    // Bayer matrix for 4x4 dithering
    float bayerMatrix[16] = float[16](
         0.0,  8.0,  2.0, 10.0,
        12.0,  4.0, 14.0,  6.0,
         3.0, 11.0,  1.0,  9.0,
        15.0,  7.0, 13.0,  5.0
    );

    // Use the base pixel position for dithering lookup
    vec2 ditherPos = mod(basePixelPos, 4.0);
    int bayerIndex = int(ditherPos.y * 4.0 + ditherPos.x);
    float threshold = (bayerMatrix[bayerIndex] + 0.5) / 16.0;

    // Apply dithering: output is either black or white depending on threshold
    float ditheredGray = step(threshold, gray);
    vec3 finalColor = vec3(ditheredGray);

    fragColor = vec4(finalColor, 1.0);
}
